const TABR: [string, number, number][] = [
  [String.raw`\sin\frac{\pi}{6}`, 1, 2], [String.raw`\cos\frac{\pi}{3}`, 1, 2], [String.raw`\mathrm{tg}\,\frac{\pi}{4}`, 1, 1], [String.raw`\cos\pi`, -1, 1],
  [String.raw`\sin\frac{5\pi}{6}`, 1, 2], [String.raw`\cos\frac{2\pi}{3}`, -1, 2], [String.raw`\sin\frac{3\pi}{2}`, -1, 1], [String.raw`\mathrm{ctg}\,\frac{3\pi}{4}`, -1, 1],
  [String.raw`\cos\frac{4\pi}{3}`, -1, 2], [String.raw`\sin\frac{7\pi}{6}`, -1, 2], [String.raw`\cos 2\pi`, 1, 1],
]
// Сумма k₁f₁ + k₂f₂ + k₃f₃ — значение в виде дроби
function combo(pool: [string, number, number][]) {
  const items = [...pool].sort(() => Math.random() - 0.5).slice(0, 3)
  const ks = items.map(() => rnd(1, 4))
  let num = 0
  items.forEach(([, p, q], i) => { num += (ks[i] * p * 2) / q })
  const expr = items.map(([s], i) => `${i ? ' + ' : ''}${ks[i] === 1 ? '' : ks[i]}${s}`).join('')
  return { expr, v: num / 2, parts: items.map(([, p, q], i) => `${ks[i]} \\cdot (${frac(p, q)})`).join(' + ') }
}

